// Shapefile reader: the records of a .shp file.
export function readRecords(buffer) {
  const view = new DataView(buffer);
  const fileBytes = view.getInt32(24, false) * 2;
  const records = [];
  let offset = 100;
  while (offset < fileBytes) {
    const length = view.getInt32(offset + 4, false) * 2;
    const type = view.getInt32(offset + 8, true);
    records.push({ type, offset: offset + 8, length });
    offset += 8 + length;
  }
  return records;
}
